import{_ as n,o as i,c as t,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const r="/bilder/datenbanken/tutorials-technisch-alive-ping.png",b=JSON.parse('{"title":"Die Datenbankverbindung durch Pings aufrechterhalten","description":"","frontmatter":{"title":"Die Datenbankverbindung durch Pings aufrechterhalten","source_pageid":1497,"source_revision":6098},"headers":[],"relativePath":"administration/datenbanken/datenbankverbindung-durch-automatische-pings-am-leben-erhalten-tutorial.md","filePath":"administration/datenbanken/datenbankverbindung-durch-automatische-pings-am-leben-erhalten-tutorial.md"}'),d={name:"administration/datenbanken/datenbankverbindung-durch-automatische-pings-am-leben-erhalten-tutorial.md"};function s(l,e,c,u,h,o){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="die-datenbankverbindung-durch-pings-aufrechterhalten" tabindex="-1">Die Datenbankverbindung durch Pings aufrechterhalten <a class="header-anchor" href="#die-datenbankverbindung-durch-pings-aufrechterhalten" aria-label="Permalink to &quot;Die Datenbankverbindung durch Pings aufrechterhalten&quot;">​</a></h1><p>Legen Sie in Admin.ini das Zeitintervall für regelmäßige Pings fest, damit die Datenbankverbindung bei längerer Untätigkeit erhalten bleibt.</p><p><a href="/bilder/datenbanken/tutorials-technisch-alive-ping.png"><img src="'+r+'" alt="Setzen Sie den automatischen Ping, um die Datenbankverbindung durch SchILD-NRW-3 am Leben zu erhalten." loading="lazy"></a></p><p><em>Setzen Sie den automatischen Ping, um die Datenbankverbindung durch SchILD-NRW-3 am Leben zu erhalten.</em></p><p>Ein <strong>Ping</strong> ist ein regelmäßig gesendetes Verbindungssignal. Sie können festlegen, in welchem Zeitabstand SchILD-NRW dieses Signal an den Datenbankserver sendet.</p><p>Dadurch wird verhindert, dass die Datenbankverbindung nach einer gewissen Zeit der Untätigkeit vom Datenbanktreiber gekappt wird.</p><p>Öffnen Sie die Datei <code>Admin.ini</code> im Installationsverzeichnis von SchILD-NRW 3. Der Eintrag im Abschnitt <code>Administration</code> lautet:</p><p><code>[Administration]</code></p><p><code>KeepConnectionAliveInterval=5</code></p><p>Der Wert gibt den Abstand zwischen den Pings in <strong>Minuten</strong> an. Im Beispiel wird alle fünf Minuten ein Signal gesendet.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Datenbankverbindung_durch_automatische_Pings_am_Leben_erhalten_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6098.</p>',12)])])}const p=n(d,[["render",s]]);export{b as __pageData,p as default};
